public interface INameStep  { IEmailStep Name(string name); }
public interface IEmailStep { IBuildStep Email(string email); }
public interface IBuildStep { User Build(); }

sealed class UserBuilder : INameStep, IEmailStep, IBuildStep {
    private string? _name; private string? _email;
    IEmailStep INameStep.Name(string n)   { _name = n;  return this; }   // explicit: not public
    IBuildStep IEmailStep.Email(string e) { _email = e; return this; }
    public User Build() => new User(_name!, _email!);
    public static INameStep Create() => new UserBuilder();
}
